cy.on('uncaught:exception', () => false);
cy.visit('/explorer-les-cartes/', {
  timeout: 30000
});
cy.get('.ol-viewport', {
  timeout: 15000
}).should('be.visible');
cy.wait(5000);
cy.document().then(doc => {
  const inputs = doc.querySelectorAll('input');
  const results = [];
  inputs.forEach((el, i) => {
    const rect = el.getBoundingClientRect();
    const cs = getComputedStyle(el);
    const vis = rect.width > 0 && rect.height > 0 && cs.display !== 'none' && cs.visibility !== 'hidden';
    results.push({
      i,
      id: el.id,
      type: el.type,
      name: el.name,
      placeholder: el.placeholder,
      cls: el.className.substring(0, 80),
      visible: vis
    });
  });
  console.table(results);
  results.forEach(r => {
    console.log(`Input[${r.i}] id="${r.id}" type="${r.type}" name="${r.name}" placeholder="${r.placeholder}" visible=${r.visible} class="${r.cls}"`);
  });
});
